// TH18 v1.00a Stage 5 Boss3 non-spell, ranks 0..3.
// Source: st05bs.ecl.txt:294-468 (Boss3 294-348, Boss3_at 350-467).
// Source t0 = Boss3 entry; the target phase adds a 120-frame opening buffer.
// Shell: control enemy at (0,0) with body collision off; the real boss at the
// source centre keeps the source hitbox/hurtbox and is invincible in training.
const TIME_LIMIT: int = 2522;   // 120 buffer + 2400 source timeout + 2
const SOURCE_LIMIT: int = 2400; // st05bs.ecl.txt:328 slot0 timeout
const OPENING_BUFFER: int = 120;

const TH18_BIG_BALL2: int = 656; // type19, radius 8.5, source color6
const TH18_STAR_R: int = 608;   // type16, radius 4, source color13
const TH18_STAR_L: int = 944;   // type37, radius 4, source color13

// B:360 record0: OFFSCREEN(a=20,b=0). Only the offscreen keep countdown is used.
xformdef BIG_KEEP {
    offscreen_keep(20);
}

// B:369-465 parent big-ball EX chain: WAIT W, SHOOT pair, GOTO index1 x20;
// then STEP c1, six WAIT8/SHOOT pairs, WAIT60. A parent is retired long before
// the STEP phase (speed 4 + OFFSCREEN20), but the chain is kept in source order.
async sub big_split() {
    var rank: int = global(GVAR_RANK);
    var w: int = 16;                 // B:362 rank wait
    if rank == 1 { w = 7; }
    if rank >= 2 { w = 6; }
    var n: int = 4;                  // B:380 SHOOT ways
    if rank == 2 { n = 5; }
    if rank == 3 { n = 6; }
    var spread: angle = 8192 as angle;       // B:372 0.785398rad
    if rank >= 2 { spread = 5461 as angle; } // B:377 0.523599rad
    // B:355/357/359: 5-way fixed ring, 4.0 single layer.
    sh_reset(0);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_count(0, n, 1);               // B:389 SHOOT c=ways, d=1 layer
    sh_speed(0, 0.8fx, 0fx);         // B:389 m=0.8, n=1.0, one layer
    // B:371 WAIT; sh_task's first run is one frame after bullet spawn.
    wait(w-1);
    for i in 0..40 {                 // B:389/418 pair, B:420 GOTO index1 x20
        if i > 0 { wait(w); }        // B:400/371 WAIT between the two shots
        if i % 2 == 0 { sh_sprite(0, TH18_STAR_R, 13); } // B:390 DATA(16,13)
        else { sh_sprite(0, TH18_STAR_L, 13); }          // B:419 DATA(37,13)
        sh_angle(0, $self_angle, spread); // SHOOT r=current angle, s=second angle
        sh_fire(0);
    }
    // B:421 STEP a=30,b=1,c=1,d=0,r=F0=0,s=3. c1 re-checks the player at the
    // segment boundary; F0 is 0 (B:335 initial 0, B:344 negation keeps zero).
    var ang: angle = $self_angle;
    for t in 0..30 {
        var v: fx = 4fx - (t as fx)*4fx/30fx;
        set_vel(0, v*cos(ang), v*sin(ang));
        wait(1);
    }
    set_angle(0, aim_player());
    set_speed(0, 3fx);
    for j in 0..6 {                  // B:440/460 pair, B:462 GOTO index10 x3
        wait(8);                     // B:422/442 WAIT8
        if j % 2 == 0 { sh_sprite(0, TH18_STAR_R, 13); }
        else { sh_sprite(0, TH18_STAR_L, 13); }
        sh_angle(0, $self_angle, spread);
        sh_fire(0);
    }
    wait(60);                        // B:464
}

// B:350-467 Boss3_at: one 5-way fixed half-offset ring of big balls per cycle.
sub boss3_at() {
    sh_reset(0);
    sh_sprite(0, TH18_BIG_BALL2, 6); // B:356 type19 color6
    sh_ring(0, 1);
    sh_aim(0, 0);                    // B:355 etAim(5): fixed direction
    sh_count(0, 5, 1);               // B:357
    // B:358 alpha=90deg, delta=20deg; mode5 adds pi/5 -> base 126deg.
    sh_angle(0, 126deg, 0deg);
    sh_speed(0, 4fx, 0fx);           // B:359 4.0/1.0 with one layer
    sh_xform(0, BIG_KEEP);
    sh_task(0, big_split);
    sh_fire(0);
}

// B:294-348 Boss3. Source 90+80 setup waits, then a 180-frame attack cycle:
// shot, wait120, moveRand(50,0,0.8), wait60, F0 flip (always 0).
async sub boss3_pattern() {
    wait(OPENING_BUFFER);
    wait(90);                        // B:330
    // B:331 EffChargePoint3 is a decorative charge effect.
    wait(80);                        // B:332
    loop {
        boss3_at();                  // B:339
        wait(120);                   // B:340
        card_move_rand();            // B:342
        card_wait(60);               // B:343
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);               // B:298 setHurtbox(40,40): half width
    set_hitbox(24fx);                // B:298 setHitbox(48,48): half width
    phase_begin(0, boss3_pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

// Synthetic controller at (0,0): hosts no attack, never body-collides.
async sub controller() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_hitbox(0fx);
    set_hurtbox(0fx);
    // Real boss starts at the upstream centre (0,128), keeps source judgement.
    _ = spawn_enemy(0fx, 128fx, 19000, 0, 0, 0, boss_main);
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, controller);
    loop { wait(600); }
}

// TH18 v1.00a st05bs.ecl Boss3 only: moveRand(50,0,0.8) under
// moveLimit(0,128,280,96). int slot0 = next-step count; fx0/1 = logical unit
// vector. The source speed slot keeps mode0 (linear), as in the moveRand recipe.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 50 { speed = 0.8fx * ((50-k) as fx) / 50fx; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 405b90 = signed unit random * pi. Values are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {            // moveLimit width 280: inner +/-width/4
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 104fx {            // height 96: inner 128 +/- 24
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05rad, nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}
